    def scope(self, id, content, **links):
        return Node(id, 'Paragraph', ('Scope',), None, content=content, links=links)

    def section(self, id, *children, **links):
        return Node(id, 'Section', children=children, links=links)

    def table(self, id, *rows):
        out = []
        for n, r in enumerate(rows, 1):
            if isinstance(r, Node):
                out.append(r)
            else:
                rid = f"{id}-r{n}"
                out.append(Node(rid, 'TableRow', (), None, children=self._items(rid + "-c", r, 'TableCell', ((), None))))
        return Node(id, 'Table', children=out)

    def table_row(self, id, *cells):
        return Node(id, 'TableRow', children=self._items(id + "-c", cells, 'TableCell', ((), None)))

    def unresolved_issue(self, id, content, **links):
        return Node(id, 'Paragraph', ('UnresolvedIssue',), None, content=content, links=links)
